fields.InputDefinition:
{
  "goal": "Open the 'MJ: AI Agent Runs' entity grid — type 'AI Agent Runs' in the LEFT sidebar 'Search entities...' box and click the 'MJ: AI Agent Runs' node (or navigate to http://localhost:4200/app/data-explorer/Data?entity=MJ:%20AI%20Agent%20Runs). Click a row whose Status is 'Completed', then click 'Open Full Record'. The AI Agent Run detail opens with a header (the agent name e.g. 'Memory Manager', a COMPLETED badge, and Started/Completed/Duration/Result fields) and a row of tabs: Timeline, Visualization, Analytics, Details. On the default 'Timeline' tab, verify the run's execution STEPS are listed — each step shows a name (e.g. 'Agent Validation', 'Load Conversations With New Activity'), a Type (e.g. Validation or Decision), a duration in ms, and a Completed status. Confirm at least the run header (Duration, Result: Success) AND one or more timeline steps are visible. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "A Completed AI Agent Run record opened showing its run header (agent name, COMPLETED, Duration, Result)",
    "The Timeline lists one or more execution steps, each with a name, type, duration, and status",
    "No error messages or crash pages"
  ]
}
